import json,html
from pathlib import Path
root=Path(__file__).resolve().parents[1]
variants=json.loads((root/'manifest.json').read_text())
def card(x):
 i=x['id'];title=html.escape(x['title']);why=html.escape(x['why'])
 sources=' · '.join(dict.fromkeys(p['sluzba'] for p in x.get('sources',[])))
 nums=', '.join(str(n) for n in x.get('photos',[]))
 note=f'<details><summary>Výběr fotografie</summary><p>{html.escape(x["note"])}</p></details>' if x.get('note') else ''
 return f'''<article id="navrh-{i}"><a class="screens" href="{i}/" aria-label="Otevřít {i} {title}"><img class="desktop" src="screenshots/{i}-desktop.webp" alt="{i}: desktop 1440 × 900" width="1440" height="900" loading="lazy"><img class="mobile" src="screenshots/{i}-mobile.webp" alt="{i}: mobil 390 × 844" width="390" height="844" loading="lazy"></a><div class="card-copy"><h2><a href="{i}/"><span>{i}</span> {title} ↗</a></h2><p>{why}</p><p class="meta">{html.escape(sources)}{(' · foto '+nums) if nums else ''}</p>{note}</div></article>'''
base={'id':'00','title':'Současná úvodní fotka','why':'Stejná homepage se současným hero pro přímé srovnání.'}
s='''<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex, nofollow"><title>20 úvodních fotografií · Tři Mistři</title><link rel="icon" href="favicon.ico"><link rel="stylesheet" href="overview.css"></head><body><header><a class="brand" href="../../">Tři Mistři<span>.</span></a><a href="00/">00 současná ↗</a></header><main><div class="intro"><p class="eyebrow">Podklady k výběru · 1. 11. 2026</p><h1>Skutečná práce.<br>První dojem.</h1><p>Dvacet možností úvodní fotografie a hera. Stejné texty, stejné odkazy, celá původní homepage. Mění se jen úvodní obraz a jeho kompozice.</p><p class="recommendation"><strong>Za mě začít návrhem <a href="01/">01</a>.</strong> Hotová ložnice, výrazná stěna a vlastní práce. Pro srovnání otevřít <a href="14/">14</a> s odděleným textem a <a href="20/">20</a> s detailem.</p><p class="fine">Náhledy: desktop 1440 × 900 a mobil 390 × 844. Fotografie návrhů jsou pouze z knihovny realizací. Současná 00 zachovává původní snímek pro porovnání. Na trimistri.cz se nic nemění. Formulář v těchto náhledech neodesílá poptávky.</p></div><section class="baseline" aria-label="Současná stránka">'''+card(base)+'''</section><div class="section-heading"><h2>20 návrhů</h2><p>Klikni na náhled. Mezi návrhy přejdeš šipkami nebo plovoucím panelem.</p></div><section class="grid" aria-label="Návrhy úvodní fotografie">'''+''.join(card(x) for x in variants)+'''</section><footer><p><strong>O výběru fotek</strong></p><p>331 → 159: volné kabely a nedokončené instalace. 316 → 332: zakrytý nábytek. 145 → 143: štítek průběh nahrazen záběrem po ze stejné realizace. Návrh 16 přebírá stejné náhrady. U 274 a 285 je záběr omezen ořezem.</p><p>18: snímky 308 před / 310 po patří stejné realizaci, ale mají odlišný úhel focení. Posuvník porovnává stav, nikoli přesně registrované pixely.</p><p>14, 15 a 18 používají krémový podklad a grafitové písmo z původní palety. Překrytí ostatních fotografií nepřesahuje původní hero-shade. 19 při omezení pohybu zobrazí jediný statický snímek.</p><p>AVIF + WebP, mobilní zdroj a velikosti 1024 / 1440 / 1920 podle rozlišení originálu, bez zvětšování souborů nad zdroj. Nejčastější originál má šířku 1200 px.</p><p><a href="verification.json">Výsledky ověření</a> · <a href="contrast.json">Měření kontrastu</a> · <a href="manifest.json">Zdroje všech fotografií</a></p></footer></main></body></html>'''
(root/'index.html').write_text(s)
